// Standard Gamepad API plus explicit calibration for raw Switch Pro layouts.
const PAD_DEFAULT={attack:7,skill1:2,skill2:3,dash:0,interact:1,flask:5,inventory:4,map:8,pause:9,gems:12,tree:13,secondary:6,accept:1,back:0};
const PAD_NAMES={attack:'通常攻撃',skill1:'第1スキル',skill2:'第2スキル',dash:'瞬歩',interact:'調べる・拾う',flask:'生命瓶',inventory:'装備',map:'地図',pause:'一時停止',gems:'ジェム',tree:'パッシブ',secondary:'追加スキル（長押し）',accept:'メニュー決定',back:'メニュー戻る'};
let padDevice=null,padPrevious=[],padProfile={menuVersion:2,actionVersion:1,buttons:{...PAD_DEFAULT},axes:[0,1,2,3],deadzone:.2,invertLY:false,invertRY:false,haptics:true,ready:false},padProfiles={},padBinding=null,padSettingsOpen=false,padMenuIndex=-1,padMenuDelay=0,padUiClock=0,padCursor={x:innerWidth/2,y:innerHeight/2,active:false},padActive=false,padAim={x:1,y:0},padRumbleTime=0,padStatusText='未接続';
try{padProfiles=JSON.parse(localStorage.getItem('ashen-pads-v1')||'{}')}catch{}
// Upgrade saved menu bindings once, retaining other calibrated inputs.
for(const profile of Object.values(padProfiles)){if(profile.menuVersion!==2){const b=profile.buttons||{};profile.buttons={...b,accept:b.back??1,back:b.accept??0};profile.menuVersion=2}}
for(const profile of Object.values(padProfiles)){if(profile.actionVersion!==1){profile.buttons={...profile.buttons,dash:profile.buttons?.back??0,interact:profile.buttons?.accept??1};profile.actionVersion=1}}
try{localStorage.setItem('ashen-pads-v1',JSON.stringify(padProfiles))}catch{}
let padEnabled=true;try{padEnabled=localStorage.getItem('ashen-pad-enabled')!=='false'}catch{}
function setPadEnabled(value){padEnabled=value;padActive=false;padCursor.active=false;try{localStorage.setItem('ashen-pad-enabled',String(value))}catch{}}
function padList(){try{return typeof navigator.getGamepads==='function'?Array.from(navigator.getGamepads()).filter(g=>g&&g.connected!==false):[]}catch{return[]}}
function persistPad(){if(!padDevice)return;padProfiles[padDevice.id]=JSON.parse(JSON.stringify(padProfile));try{localStorage.setItem('ashen-pads-v1',JSON.stringify(padProfiles))}catch{}}
function connectPad(g){padDevice=g;let saved=padProfiles[g.id];padProfile={menuVersion:2,actionVersion:1,buttons:{...PAD_DEFAULT,...saved?.buttons},axes:saved?.axes||[0,1,2,3],deadzone:saved?.deadzone??.2,invertLY:!!saved?.invertLY,invertRY:!!saved?.invertRY,haptics:saved?.haptics!==false,ready:g.mapping==='standard'||!!saved?.ready};padPrevious=g.buttons.map(b=>b.pressed||b.value>.5);padStatusText=padProfile.ready?'接続済み':'非標準配置・設定が必要';if(started)say('ゲームパッド '+padStatusText);if(padSettingsOpen)showControllerSettings();refreshPadBadge()}
function radialStick(x,y,deadzone){let magnitude=Math.hypot(x,y);if(!Number.isFinite(magnitude)||magnitude<=deadzone)return{x:0,y:0,magnitude:0};let amount=Math.min(1,(magnitude-deadzone)/(1-deadzone));return{x:x/magnitude*amount,y:y/magnitude*amount,magnitude:amount}}
function padDown(g,action){let b=g.buttons[padProfile.buttons[action]];return !!b&&(b.pressed||b.value>.5)}
function padEdge(g,action){return padDown(g,action)&&!padPrevious[padProfile.buttons[action]]}
// Placement abilities require a new button press so holding cannot waste mana.
function padSkillDown(g,action,n){let type=p?.bindings?.[skillBindingIndex(n)];return typeof GEM!=='undefined'&&GEM[type]?.pressOnly?padEdge(g,action):padDown(g,action)}
function padButtonEdge(g,index){let b=g.buttons[index];return !!b&&(b.pressed||b.value>.5)&&!padPrevious[index]}
function refreshPadBadge(){let b=$('padBadge');if(b)b.textContent=padDevice?(padProfile.ready?'🎮 接続中':'🎮 設定が必要'):'🎮 設定'}
function rumble(strength=.25,duration=70){if(!padDevice||!padProfile.haptics||performance.now()<padRumbleTime)return;padRumbleTime=performance.now()+70;try{let actuator=padDevice.vibrationActuator;if(actuator?.playEffect)Promise.resolve(actuator.playEffect('dual-rumble',{duration,startDelay:0,strongMagnitude:strength,weakMagnitude:strength*.6})).catch(()=>{})}catch{}}
function padSetAxis(slot,value){padProfile.axes[slot]=Math.max(0,+value||0);persistPad()}
function padSetPreference(key,value){padProfile[key]=value;persistPad()}
function padBeginBinding(action){padBinding={action,armed:false};let el=$('bindingMessage');if(el)hudText(el,PAD_NAMES[action]+'：いったん全ボタンを離し、割り当てたいボタンを押す')}
function padCancelBinding(){padBinding=null;if($('bindingMessage'))hudText($('bindingMessage'),'割り当てを中止しました')}
function padCapture(g){if(!padBinding)return false;let pressed=g.buttons.map((b,i)=>(b.pressed||b.value>.5)?i:-1).filter(i=>i>=0);if(!padBinding.armed){if(!pressed.length)padBinding.armed=true;return true}let first=pressed.find(i=>!padPrevious[i]);if(first!==undefined){padProfile.buttons[padBinding.action]=first;persistPad();padBinding=null;showControllerSettings();if($('bindingMessage'))hudText($('bindingMessage'),'ボタン '+first+' を登録しました')}return true}
function padApplyRaw(){padProfile.ready=true;persistPad();padStatusText='接続済み';showControllerSettings()}
function padReset(){if(padDevice)delete padProfiles[padDevice.id];try{localStorage.setItem('ashen-pads-v1',JSON.stringify(padProfiles))}catch{}if(padDevice)connectPad(padDevice);showControllerSettings()}
function escapePad(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function closeControllerSettings(){padSettingsOpen=false;padBinding=null;padCursor.active=false;if(started&&!dead)closePanel();else if(!started){$('card').classList.remove('wide');welcome();}else{ $('card').innerHTML='<h2>灰に還る</h2><button onclick="dead=false;enterFloor();closePanel()">再挑戦</button>'}}
function showControllerSettings(){paused=true;keys={};route=[];attackTarget=null;leftDown=false;rightDown=false;padSettingsOpen=true;padMenuIndex=-1;$('modal').classList.remove('hidden');$('card').classList.add('wide');let g=padDevice,axesCount=g?.axes.length||4;let h='<button class="close" onclick="closeControllerSettings()">閉じる ×</button><label>SOUND / EFFECTS / CONTROLLER</label><h2>音・演出・プロコン設定</h2><div class="device-status"><b id="padConnection">'+(g?escapePad(g.id):'コントローラー未接続')+'</b><p>'+ (g?(g.mapping==='standard'?'標準配置':'非標準配置：軸とボタンを登録して「この設定を使用」を押してください'):'PCにUSBまたはBluetoothで接続して、いずれかのボタンを押してください。')+'</p><span id="padLive">入力待ち</span></div><div class="settings-grid"><section><h3>サウンド</h3><button onclick="toggleAudio()">音を有効化 / ミュート</button><p class="muted">最初に一度、画面をクリックすると音が有効になります。Mでも切替。</p>'+[['master','全体'],['effects','効果音'],['music','BGM'],['ambience','環境音']].map(([key,label])=>'<label class="slider-label">'+label+'<input type="range" min="0" max="1" step=".01" value="'+audioPrefs[key]+'" oninput="changeAudio(\''+key+'\',this.value)"></label>').join('')+'<button onclick="unlockAudio().then(()=>playSound(\'fire\'))">音のテスト</button><h3>描画と演出の負荷</h3><select aria-label="エフェクト品質" aria-describedby="renderQualityHelp" onchange="setEffectQuality(this.value)"><option value="high" '+(effectQuality==='high'?'selected':'')+'>高品質</option><option value="low" '+(effectQuality==='low'?'selected':'')+'>軽量</option></select><p id="renderQualityHelp" class="muted">軽量：景色を少し粗くして描画負荷を軽減。メニュー文字・攻撃予兆・操作速度は維持。</p></section><section><h3>スティック</h3><label><input type="checkbox" '+(padEnabled?'checked':'')+' onchange="setPadEnabled(this.checked)">ゲームパッド入力を有効にする</label>'+ ['左 X','左 Y','右 X（照準）','右 Y（照準）'].map((label,i)=>'<label class="axis-label">'+label+'<select onchange="padSetAxis('+i+',this.value)">'+Array.from({length:axesCount},(_,j)=>'<option value="'+j+'" '+(padProfile.axes[i]===j?'selected':'')+'>Axis '+j+'</option>').join('')+'</select></label>').join('')+'<label class="slider-label">デッドゾーン<input type="range" min=".05" max=".4" step=".01" value="'+padProfile.deadzone+'" oninput="padSetPreference(\'deadzone\',+this.value)"></label><label><input type="checkbox" '+(padProfile.invertLY?'checked':'')+' onchange="padSetPreference(\'invertLY\',this.checked)">左Y反転</label> <label><input type="checkbox" '+(padProfile.invertRY?'checked':'')+' onchange="padSetPreference(\'invertRY\',this.checked)">右Y反転</label><p><label><input type="checkbox" '+(padProfile.haptics?'checked':'')+' onchange="padSetPreference(\'haptics\',this.checked)">振動（対応環境のみ）</label></p><button onclick="padApplyRaw()" '+(!g?'disabled':'')+'>この設定を使用</button> <button onclick="padReset()">初期配置</button></section></div><h3>ボタン割り当て</h3><p id="bindingMessage">項目を選び、コントローラーのボタンを押して登録。</p><div class="pad-bindings">'+Object.keys(PAD_NAMES).map(a=>'<button onclick="padBeginBinding(\''+a+'\')" '+(!g?'disabled':'')+'>'+PAD_NAMES[a]+'<small>Button '+padProfile.buttons[a]+'</small></button>').join('')+'</div><button onclick="padCancelBinding()">割り当て中止</button><p class="muted">標準プロコン配置：左スティック移動、右スティック照準（浅く倒すと近く、深く倒すと遠く。離すと維持、左スティック移動で自動照準に戻る）、ZR攻撃、L第1スキル、R第2スキル、ZL＋X/Y/A/Bで追加4スキル、B回避、A調べる、Yポーション1、ZL＋R/Lでポーション2/3、X装備、−地図、＋一時停止、↑ジェム、↓パッシブ。装備画面は十字キー／左スティックでアイテムを選択し、Aで操作を選びます。Bで一段戻り、Xで画面を閉じます。L/Rで装備・ジェム・成長を切替。その他のメニューも十字キーで上下左右に選択、A決定、B戻る。右スティックで説明をスクロール。ツリーは左スティックでスクロール、十字キーでノード選択、Aで取得操作へ、Bでノードへ戻ります。</p>';$('card').innerHTML=h;refreshAudioBadge()}
function padClickAtCursor(){let target=document.elementFromPoint(padCursor.x,padCursor.y)?.closest('button,[role="button"],input,select');if(!target||target.disabled)return;target.focus?.();if(target.tagName==='SELECT'){let i=(target.selectedIndex+1)%target.options.length;target.selectedIndex=i;target.dispatchEvent(new Event('change',{bubbles:true}))}else if(target.type==='range'){let box=target.getBoundingClientRect(),v=(padCursor.x-box.left)/box.width;target.value=+target.min+clamp(v,0,1)*(+target.max-+target.min);target.dispatchEvent(new Event('input',{bubbles:true}))}else if(typeof target.click==='function')target.click();else target.dispatchEvent(new MouseEvent('click',{bubbles:true}));playSound('ui')}
function padFocusMenu(direction){let items=Array.from($('card').querySelectorAll('button:not(:disabled),select,input,[role="button"]')).filter(el=>{let r=el.getBoundingClientRect();return r.width>0&&r.height>0});if(!items.length)return;let current=items.indexOf(document.activeElement);padMenuIndex=(current+direction+items.length)%items.length;items[padMenuIndex].focus();items[padMenuIndex].scrollIntoView({block:'nearest'});padCursor.active=false}
function padMenu(g,left,right,dt){padMenuDelay-=dt;if(padEdge(g,'pause')&&started&&!dead){if(padSettingsOpen)closeControllerSettings();else closePanel();return}if(padEdge(g,'back')){if(padSettingsOpen)closeControllerSettings();else if(started&&!dead)closePanel();return}if(right.magnitude){padCursor.active=true;padCursor.x=clamp(padCursor.x+right.x*550*dt,8,W-8);padCursor.y=clamp(padCursor.y+right.y*550*dt,8,H-8)}let vp=$('treeViewport');if(vp&&$('card').contains(vp)&&left.magnitude){vp.scrollLeft+=left.x*600*dt;vp.scrollTop+=left.y*600*dt}else if(left.magnitude>.5&&padMenuDelay<=0){padFocusMenu(left.y<0||left.x<0?-1:1);padMenuDelay=.22}if(padButtonEdge(g,12)||padButtonEdge(g,14))padFocusMenu(-1);if(padButtonEdge(g,13)||padButtonEdge(g,15))padFocusMenu(1);if(padEdge(g,'accept')){if(padCursor.active)padClickAtCursor();else{let el=document.activeElement;if(el&&$('card').contains(el)&&!el.disabled){if(el.tagName==='SELECT'){el.selectedIndex=(el.selectedIndex+1)%el.options.length;el.dispatchEvent(new Event('change',{bubbles:true}))}else if(typeof el.click==='function')el.click();else el.dispatchEvent(new MouseEvent('click',{bubbles:true}))}else padFocusMenu(1)}}}
function padAimAt(right,left){let aim=right.magnitude>.1?right:left.magnitude>.1?left:padAim;if(right.magnitude>.1||left.magnitude>.1)padAim={x:aim.x,y:aim.y};let target=null;if(right.magnitude<.1){target=enemies.filter(e=>e.hp>0&&visibleAt(e.x,e.y)&&dist(p,e)<360&&lineClear(p,e)).sort((a,b)=>dist(p,a)-dist(p,b))[0]}if(target){let screen=project(target.x,target.y);mouse={x:screen.x,y:screen.y}}else{let mag=Math.hypot(aim.x,aim.y)||1;mouse={x:W/2+aim.x/mag*240,y:H/2+aim.y/mag*240}}}
let padWindowActive=typeof document.hasFocus!=='function'||document.hasFocus();addEventListener('focus',()=>{padWindowActive=true});addEventListener('blur',()=>{padWindowActive=false});
function padFrame(dt){if(!padEnabled||document.hidden||!padWindowActive){padPrevious=padList().find(g=>g.index===padDevice?.index)?.buttons.map(b=>b.pressed||b.value>.5)||[];return null}let pads=padList(),g=padDevice?pads.find(v=>v.index===padDevice.index&&v.id===padDevice.id):null;if(!g&&pads.length)g=pads[0];if(!g){if(padDevice){padDevice=null;padActive=false;padPrevious=[];padCursor.active=false;if(started&&!paused)panel('pause');padStatusText='切断されました';refreshPadBadge();if(padSettingsOpen)showControllerSettings()}return null}if(!padDevice||g.id!==padDevice.id||g.index!==padDevice.index)connectPad(g);padDevice=g;let pressed=g.buttons.map(b=>b.pressed||b.value>.5);padUiClock-=dt;if(padSettingsOpen&&padUiClock<=0){padUiClock=.15;let live=$('padLive');if(live)live.textContent=g.axes.map((v,i)=>'A'+i+' '+v.toFixed(2)).join(' · ')+' | 押下 '+pressed.map((v,i)=>v?i:null).filter(v=>v!==null).join(', ')}if(padCapture(g)){padPrevious=pressed;return null}if(!padProfile.ready){padPrevious=pressed;return null}let [lx,ly,rx,ry]=padProfile.axes,left=radialStick(g.axes[lx]||0,(g.axes[ly]||0)*(padProfile.invertLY?-1:1),padProfile.deadzone),right=radialStick(g.axes[rx]||0,(g.axes[ry]||0)*(padProfile.invertRY?-1:1),padProfile.deadzone);let active=left.magnitude||right.magnitude||pressed.some(Boolean);if(active)padActive=true;if(paused||!started){padMenu(g,left,right,dt)}else{if(left.magnitude){route=[];attackTarget=null;lootTarget=null}if(active)padAimAt(right,left);if(padEdge(g,'pause'))panel('pause');else if(!padDown(g,'secondary')&&padEdge(g,'inventory'))panel('inventory');else if(padEdge(g,'gems'))panel('gems');else if(padEdge(g,'tree'))panel('skills');else if(padEdge(g,'map'))mapOpen=!mapOpen;else{let dodgeRequested=!padDown(g,'secondary')&&padEdge(g,'dash');if(!dodgeRequested){if(padDown(g,'attack')){attackTarget=null;cast(0)}if(padDown(g,'secondary')){if(typeof drinkPotion==='function'){if(padEdge(g,'potion2'))drinkPotion(1);if(padEdge(g,'potion3'))drinkPotion(2);}if(padSkillDown(g,typeof drinkPotion==='function'?'skill3':'skill1',4))cast(4);if(padSkillDown(g,typeof drinkPotion==='function'?'skill4':'skill2',5))cast(5);if(padSkillDown(g,'accept',6))cast(6);if(padSkillDown(g,'back',7))cast(7)}else{if(padSkillDown(g,'skill1',1))cast(1);if(padSkillDown(g,'skill2',2))cast(2)}}if(dodgeRequested){let oldMouse=mouse;if(left.magnitude)mouse={x:W/2+left.x*240,y:H/2+left.y*240};cast(3);mouse=oldMouse};if(!padDown(g,'secondary')&&padEdge(g,'flask'))heal();if(!padDown(g,'secondary')&&padEdge(g,'interact'))interact()}}padPrevious=pressed;padUiClock-=dt;if(padSettingsOpen&&padUiClock<=0){padUiClock=.15;let live=$('padLive');if(live)live.textContent=g.axes.map((v,i)=>'A'+i+' '+v.toFixed(2)).join(' · ')+' | 押下 '+pressed.map((v,i)=>v?i:null).filter(v=>v!==null).join(', ')}return left}
let padFootTimer=0;const padUpdate=update;update=dt=>{let stick=padFrame(dt);padUpdate(dt);if(stick?.magnitude&&started&&!paused&&!playerAction&&!dead&&!['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].some(k=>keys[k])){let dx=stick.x+stick.y,dy=stick.y-stick.x,len=Math.hypot(dx,dy)||1,speed=205*(1+Math.min(.8,stat('speed')/100))*stick.magnitude;playerMoving=moveActor(p,dx/len*speed*dt,dy/len*speed*dt)>.1;face=stick.x<-.1?-1:stick.x>.1?1:face;padFootTimer-=dt;if(playerMoving&&padFootTimer<=0){padFootTimer=.28;playSound('step')}}let cursor=$('padCursor');if(cursor){cursor.style.display=padDevice&&padCursor.active&&paused?'block':'none';cursor.style.left=padCursor.x+'px';cursor.style.top=padCursor.y+'px'}};
const padHit=hit;hit=(e,d)=>{let hp=e.hp;padHit(e,d);if(e.hp<hp&&padActive)rumble(e.hp<=0?.35:.16,55)};const padHurt=hurt;hurt=d=>{let hp=p.hp;padHurt(d);if(p.hp<hp&&padActive)rumble(.55,110)};
const padPanel=panel;panel=kind=>{padSettingsOpen=false;padBinding=null;padMenuIndex=-1;padPanel(kind)};
const padHud=drawHud;drawHud=()=>{padHud();if(padActive&&padDevice){hudText(document.querySelector('.hint'),'左スティック 移動 · 右スティック 照準 · ZR 攻撃 · L / R スキル · B 回避 · A 調べる · ＋ 停止')}else hudText(document.querySelector('.hint'),'左クリック 移動・攻撃 · SHIFT その場攻撃 · 右クリック スキル · WASD 移動 · TAB 地図 · F 調べる')};
addEventListener('mousemove',()=>{padActive=false});addEventListener('keydown',()=>{padActive=false});addEventListener('gamepadconnected',e=>connectPad(e.gamepad));addEventListener('gamepaddisconnected',()=>{padPrevious=[]});
document.querySelector('.menu').insertAdjacentHTML('afterbegin','<button id="padBadge" onclick="showControllerSettings()">🎮 設定</button>');document.body.insertAdjacentHTML('beforeend','<div id="padCursor" aria-hidden="true">◇</div>');



